{"content": "\set VERBOSITY terse
\echo '================ TABLAS CREADAS ================'
select tablename from pg_tables where schemaname='public' order by 1;

\echo '================ FOREIGN KEYS Y REGLA DE BORRADO ================'
select conrelid::regclass::text as tabla,
       conname as fk,
       confrelid::regclass::text as referencia,
       case confdeltype
         when 'a' then 'NO ACTION' when 'r' then 'RESTRICT'
         when 'c' then 'CASCADE'   when 'n' then 'SET NULL'
         when 'd' then 'SET DEFAULT' end as on_delete
from pg_constraint
where contype='f' and connamespace='public'::regnamespace
order by 1,2;

\echo '================ CHECK CONSTRAINTS ================'
select conrelid::regclass::text as tabla, conname
from pg_constraint
where contype='c' and connamespace='public'::regnamespace
order by 1,2;

\echo '================ INDICES UNICOS PARCIALES ================'
select indexname from pg_indexes
where schemaname='public' and indexdef ilike '%where%' order by 1;

\echo '================ TIPOS jsonb / timestamptz / numeric ================'
select table_name, column_name, data_type
from information_schema.columns
where table_schema='public'
  and data_type in ('jsonb','timestamp with time zone','numeric')
order by table_name, ordinal_position;

\echo '================ DATOS VALIDOS (deben pasar) ================'
insert into users (nombre,email,password,rol,activo,created_at,updated_at)
values ('Admin Uno','admin@test.bo','hash','administrador',true,now(),now());
insert into users (nombre,email,password,rol,activo,created_at,updated_at)
values ('Operador Uno','operador@test.bo','hash','operador',true,now(),now());

insert into recetas (user_id,nombre,tipo_producto,ingrediente_base,peso,tipo_aceite,calculos,aditivos,created_at,updated_at)
select id,'Receta base','barra','aceite',1000,'oliva','{"aceite":1000,"agua":380,"sosa":140}'::jsonb,'[]'::jsonb,now(),now()
from users where email='admin@test.bo';

insert into perfiles (user_id,nombre,configuraciones_json,es_predeterminado,created_at,updated_at)
select id,'Perfil produccion','{"pwm":{"filter1":250,"water":200,"oil":250,"filter2":250,"pump4":250,"l298n1":150,"motor3":150}}'::jsonb,true,now(),now()
from users where email='admin@test.bo';

insert into lotes (codigo,user_id,receta_id,perfil_id,fecha_inicio,estado,created_at,updated_at)
select 'LOTE-2026-0001', u.id, r.id, p.id, now(), 'en_proceso', now(), now()
from users u, recetas r, perfiles p
where u.email='admin@test.bo' and r.nombre='Receta base' and p.nombre='Perfil produccion';

insert into pedidos (user_id,cliente,cantidad_unidades,estado,fecha_entrega,created_at,updated_at)
select id,'Cliente Test',10,'pendiente',current_date + 7,now(),now()
from users where email='operador@test.bo';

insert into pedido_lote (pedido_id,lote_id,created_at,updated_at)
select pe.id, l.id, now(), now() from pedidos pe, lotes l
where pe.cliente='Cliente Test' and l.codigo='LOTE-2026-0001';

insert into logs_acciones (user_id,accion,componente,origen,fecha_hora)
select id,'FILTER1 ON','FILTER1','web',now() from users where email='operador@test.bo';
insert into logs_acciones (user_id,accion,componente,origen,fecha_hora)
values (null,'L298N1 ON por molde lleno','L298N1','automatizacion',now());
insert into historial_temperaturas (temperatura,fecha_hora) values (34.75, now());
insert into reportes_generados (user_id,tipo,ruta_archivo,fecha)
select id,'lotes','reportes/lotes.pdf',now() from users where email='admin@test.bo';
insert into chatbot_historial (user_id,pregunta,respuesta,fecha_hora)
values (null,'Cuantos pedidos pendientes hay?','Hay 1 pedido pendiente.',now());

\echo '================ PRUEBAS DE INTEGRIDAD (deben FALLAR) ================'
\echo '-- 1) segundo administrador (indice unico parcial)'
insert into users (nombre,email,password,rol,activo,created_at,updated_at)
values ('Admin Dos','admin2@test.bo','hash','administrador',true,now(),now());

\echo '-- 2) receta con peso 0 (check)'
insert into recetas (user_id,nombre,tipo_producto,ingrediente_base,peso,calculos,created_at,updated_at)
select id,'Receta invalida','barra','aceite',0,'{}'::jsonb,now(),now() from users where email='admin@test.bo';

\echo '-- 3) pedido sin peso ni unidades (check)'
insert into pedidos (user_id,cliente,estado,created_at,updated_at)
select id,'Pedido vacio','pendiente',now(),now() from users where email='operador@test.bo';

\echo '-- 4) lote con fecha_fin anterior a fecha_inicio (check)'
insert into lotes (codigo,user_id,receta_id,fecha_inicio,fecha_fin,estado,created_at,updated_at)
select 'LOTE-MAL', u.id, r.id, now(), now() - interval '1 day', 'pendiente', now(), now()
from users u, recetas r where u.email='admin@test.bo' and r.nombre='Receta base';

\echo '-- 5) temperatura fuera del rango del DS18B20 (check)'
insert into historial_temperaturas (temperatura,fecha_hora) values (200.00, now());

\echo '-- 6) segundo lote para el mismo pedido (unique pivote)'
insert into pedido_lote (pedido_id,lote_id,created_at,updated_at)
select pe.id, l.id, now(), now() from pedidos pe, lotes l
where pe.cliente='Cliente Test' and l.codigo='LOTE-2026-0001';

\echo '-- 7) borrar un usuario con recetas (restrict)'
delete from users where email='admin@test.bo';

\echo '-- 8) receta inexistente (FK)'
insert into lotes (codigo,user_id,receta_id,fecha_inicio,estado,created_at,updated_at)
select 'LOTE-FK', id, 999999, now(), 'pendiente', now(), now() from users where email='admin@test.bo';

\echo '================ CASCADA EN EL PIVOTE ================'
select 'pivote antes' as momento, count(*) as filas from pedido_lote;
delete from pedidos where cliente='Cliente Test';
select 'pivote despues' as momento, count(*) as filas from pedido_lote;

\echo '================ ESTADO FINAL ================'
select 'users' as tabla, count(*) from users
union all select 'recetas', count(*) from recetas
union all select 'perfiles', count(*) from perfiles
union all select 'lotes', count(*) from lotes
union all select 'pedidos', count(*) from pedidos
union all select 'pedido_lote', count(*) from pedido_lote
union all select 'logs_acciones', count(*) from logs_acciones
union all select 'historial_temperaturas', count(*) from historial_temperaturas
union all select 'reportes_generados', count(*) from reportes_generados
union all select 'chatbot_historial', count(*) from chatbot_historial
order by 1;
", "file_path": "C:\Users\io\Documents\PROYECTO\proyectolocal\_verify.sql"}

