use App\Models\Lote;
use App\Models\Pedido;
use App\Models\Perfil;
use App\Models\Receta;
use App\Models\ReporteGenerado;
use App\Models\User;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\DB;

require __DIR__.'/vendor/autoload.php';

$app = require __DIR__.'/bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();

$ok = 0;
$bad = 0;

function check(string $label, bool $cond, string $detalle = ''): void
{
    global $ok, $bad;
    if ($cond) {
        $ok++;
        echo "  [OK]    {$label}\n";
    } else {
        $bad++;
        echo "  [FALLO] {$label} {$detalle}\n";
    }
}

$db = DB::connection();
$db->beginTransaction();

try {
    echo "== Usuarios y permisos por rol ==\n";
    $admin = User::factory()->administrador()->create(['nombre' => 'Admin Verificación', 'email' => 'verif-admin@test.bo']);
    check('rol se castea al enum Rol', $admin->rol instanceof App\Enums\Rol);
    check('administrador gestiona usuarios', $admin->puedeGestionarUsuarios());

    $op = User::factory()->operador()->create(['nombre' => 'Operador', 'email' => 'verif-op@test.bo']);
    check('operador controla la máquina', $op->puedeControlarMaquina());
    check('operador NO gestiona usuarios', ! $op->puedeGestionarUsuarios());

    $vis = User::factory()->visualizador()->create(['nombre' => 'Visitante', 'email' => 'verif-vis@test.bo']);
    check('visualizador NO controla la máquina', ! $vis->puedeControlarMaquina());
    check('visualizador NO ve reportes', ! $vis->puedeVerReportes());

    echo "== Administrador único (modelo + índice parcial) ==\n";
    $rechazado = false;
    try {
        User::factory()->administrador()->create(['email' => 'verif-admin2@test.bo']);
    } catch (QueryException $e) {
        $rechazado = str_contains($e->getMessage(), 'users_unico_administrador');
    }
    check('segundo administrador rechazado por PostgreSQL', $rechazado);

    echo "== Receta ==\n";
    $receta = Receta::create([
        'user_id' => $admin->id,
        'nombre' => 'Receta de verificación',
        'tipo_producto' => TipoProducto::Barra,
        'ingrediente_base' => IngredienteBase::Aceite,
        'peso' => 1000,
        'tipo_aceite' => 'oliva',
        'calculos' => ['aceite' => 1000, 'agua' => 380, 'sosa' => 140],
        'aditivos' => [['nombre' => 'aceite esencial', 'gramos' => 15]],
    ]);
    $receta->refresh();
    check('ingrediente_base es enum', $receta->ingrediente_base === IngredienteBase::Aceite);
    check('calculos vuelve como array', is_array($receta->calculos));
    check('pesoDe("agua") = 380', abs($receta->pesoDe('agua') - 380.0) < 0.001);
    check('relación receta->user', $receta->user->id === $admin->id);

    echo "== Perfil ==\n";
    $perfil = Perfil::create([
        'user_id' => $admin->id,
        'nombre' => 'Perfil de verificación',
        'es_predeterminado' => true,
        'configuraciones_json' => ['pwm' => ['water' => 201]],
    ]);
    $pwm = $perfil->pwm();
    check('el PWM guardado manda (water=201)', $pwm['water'] === 201);
    check('los PWM ausentes se rellenan (filter1=250)', $pwm['filter1'] === 250);
    check('configuración normalizada completa', array_keys($perfil->configuracionNormalizada()) === ['pwm', 'automatizacion_ir', 'intervalos_aceite']);

    echo "== Lote ==\n";
    $lote = Lote::create([
        'codigo' => 'LOTE-CHK-0001',
        'user_id' => $admin->id,
        'receta_id' => $receta->id,
        'perfil_id' => $perfil->id,
        'fecha_inicio' => now(),
        'estado' => EstadoLote::EnProceso,
    ]);
    check('estado es enum EstadoLote', $lote->estado === EstadoLote::EnProceso);
    check('configuracion() hereda del perfil', $lote->configuracion()['pwm']['water'] === 201);
    $lote->update(['fecha_fin' => now()->addMinutes(5), 'estado' => EstadoLote::Completado]);
    check('duración calculada = 300 s', $lote->fresh()->duracionEnSegundos() === 300);
    check('scope enProceso no lo incluye', Lote::enProceso()->whereKey($lote->id)->count() === 0);

    echo "== Pedido y pivote muchos a muchos ==\n";
    $pedido = Pedido::create([
        'user_id' => $op->id,
        'cliente' => 'Cliente Verificación',
        'cantidad_unidades' => 12,
        'estado' => App\Enums\EstadoPedido::Pendiente,
        'fecha_entrega' => now()->addWeek(),
    ]);
    check('descripcionCantidad()', $pedido->descripcionCantidad() === '12 unidades');
    $pedido->lotes()->attach($lote->id);
    check('pivote visible desde el pedido', $pedido->lotes()->count() === 1);
    check('pivote visible desde el lote', $lote->pedidos()->count() === 1);
    check('pivote guarda timestamps', $pedido->lotes()->first()->pivot->created_at !== null);

    $duplicado = false;
    try {
        $pedido->lotes()->attach($lote->id);
    } catch (QueryException $e) {
        $duplicado = str_contains($e->getMessage(), 'pedido_lote_pedido_id_lote_id_unique');
    }
    check('no se duplica la asignación lote↔pedido', $duplicado);

    $pedido->lotes()->sync([]);
    $pedido->lotes()->attach($lote->id);
    $pedido->delete();
    check('borrar el pedido limpia el pivote', DB::table('pedido_lote')->where('pedido_id', $pedido->id)->count() === 0);

    $pedidoInvalido = false;
    try {
        Pedido::create(['user_id' => $op->id, 'cliente' => 'Sin cantidad']);
    } catch (QueryException $e) {
        $pedidoInvalido = str_contains($e->getMessage(), 'pedidos_cantidad_requerida');
    }
    check('pedido sin cantidad rechazado', $pedidoInvalido);

    echo "== Logs y series temporales (sin created_at) ==\n";
    $log = LogAccion::create([
        'user_id' => null,
        'accion' => 'L298N1 ON por molde lleno',
        'componente' => 'L298N1',
        'origen' => OrigenAccion::Automatizacion,
    ]);
    check('log sin timestamps se guarda', $log->exists);
    check('origen es enum', $log->origen === OrigenAccion::Automatizacion);
    check('fecha_hora la pone la base de datos', $log->fresh()->fecha_hora !== null);

    $temp = HistorialTemperatura::create(['temperatura' => 36.5]);
    check('temperatura decimal(5,2)', (float) $temp->fresh()->temperatura === 36.5);
    check('fecha_hora automática en temperatura', $temp->fresh()->fecha_hora !== null);

    $reporte = ReporteGenerado::create(['user_id' => $admin->id, 'tipo' => 'lotes', 'ruta_archivo' => 'reportes/x.pdf']);
    check('reporte con fecha automática', $reporte->fresh()->fecha !== null);

    $chat = ChatbotHistorial::create(['pregunta' => '¿Cuántos pedidos pendientes hay?', 'respuesta' => 'Hay 1 pedido pendiente.']);
    check('chatbot sin usuario autenticado', $chat->fresh()->fecha_hora !== null);

    echo "== Baja lógica del administrador ==\n";
    $admin->delete();
    check('soft delete activo', User::withTrashed()->find($admin->id)->trashed());
    $nuevoAdmin = User::factory()->administrador()->create(['email' => 'verif-admin3@test.bo']);
    check('se puede nombrar un nuevo administrador', $nuevoAdmin->esAdministrador());
} finally {
    $db->rollBack();
}

echo "\n---------------------------------------------\n";
echo "Resultado: {$ok} correctas, {$bad} fallidas\n";
echo "Datos revertidos (rollback); la base queda vacía.\n";

exit($bad === 0 ? 0 : 1);
