{"content": "<?php

declare(strict_types=1);

use App\Models\Perfil;
use App\Models\User;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\DB;

require __DIR__.'/vendor/autoload.php';

$app = require __DIR__.'/bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();

$db = DB::connection();
$db->beginTransaction();

try {
    Artisan::call('db:seed', ['--force' => true]);
    echo trim(Artisan::output())."\n";

    $admin = User::where('email', 'admin@jabon.local')->first();
    $perfil = Perfil::where('es_predeterminado', true)->first();

    $checks = [
        'seeder crea el administrador' => $admin !== null,
        'el seeder asigna rol administrador' => $admin?->esAdministrador() === true,
        'la contraseña queda hasheada' => $admin !== null && str_starts_with($admin->password, '$2y$'),
        'el seeder crea el perfil predeterminado' => $perfil !== null,
        'el perfil trae los PWM del sistema' => $perfil?->pwm()['water'] === 200,
        'el perfil define automatización IR' => ($perfil?->automatizacionIr()['tiempo_agitacion_s'] ?? null) === 30,
    ];

    $bad = 0;
    foreach ($checks as $label => $cond) {
        echo ($cond ? '  [OK]    ' : '  [FALLO] ').$label."\n";
        $bad += $cond ? 0 : 1;
    }

    echo $bad === 0 ? "\nSeeder correcto.\n" : "\nSeeder con {$bad} fallo(s).\n";
} finally {
    $db->rollBack();
    echo "Datos revertidos; la base queda vacía.\n";
}

exit(($bad ?? 0) === 0 ? 0 : 1);
