            'esp32' => $estado,
            'servidor' => now()->toIso8601String(),
            'programaciones' => Programacion::activas()->count(),
        ]);
    }

    public function comando(Request $request): JsonResponse
    {
        $datos = $request->validate(['comando' => ['required','string','max:60']]);
