        if (! $this->esp32->comandoValido($comando)) {
            return response()->json(['ok'=>false,'mensaje'=>"Comando no permitido: {$comando}"], 422);
        }

        $resultado = $this->esp32->enviar($comando);
        $this->registrarLog($request, $comando, $this->componenteDe($comando));

