        session put
        $perfil = Perfil::findOrFail
        $pwm = $perfil->pwm()
        foreach mapping: FILTER1=>filter1, WATER=>water, OIL=>oil, FILTER2=>filter2, PUMP4=>pump4, V=>l298n1, MOTOR3 SPEED=>motor3
        send commands, collect results
        return json with enviados
    }

    public function programar(Request $request): JsonResponse
    {
        $datos = $request->validate([
            'comando' => ['required','string','max:60'],
            'componente' => ['required','string', Rule::in(array_keys(Esp32Service::COMPONENTES))],
            'tipo' => ['required', Rule::in(['retardo','diaria'])],
            'segundos' => ['required_if:tipo,retardo','nullable','integer','min:1','max:86400'],
