namespace App\Http\Controllers;

use App\Enums\EstadoLote;
use App\Enums\EstadoPedido;
use App\Models\ChatbotHistorial;
use App\Models\HistorialTemperatura;
use App\Models\LogAccion;
use App\Models\Lote;
use App\Models\Pedido;
use App\Models\Receta;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\View\View;

class DashboardController extends Controller
{
    public function index(Request $request): View
    {
        $ultimaTemperatura = HistorialTemperatura::orderByDesc('fecha_hora')->first();

        return view('dashboard', [
            'temperatura' => $ultimaTemperatura,
            'pedidosPendientes' => Pedido::abiertos()->count(),
            'ultimoLote' => Lote::with('receta')->orderByDesc('fecha_inicio')->first(),
            'totalRecetas' => Receta::count(),
            'lotesCompletados' => Lote::where('estado', EstadoLote::Completado)->count(),
            'actividad' => LogAccion::with('user')->orderByDesc('fecha_hora')->limit(6)->get(),
            'conversacion' => ChatbotHistorial::where('user_id', $request->user()->id)
                ->orderBy('fecha_hora')
                ->limit(10)
                ->get(),
            'sugerencias' => \App\Services\ChatbotService::SUGERENCIAS,
            'pedidosRecientes' => Pedido::where('estado', EstadoPedido::Pendiente)
                ->orderBy('fecha_entrega')
                ->limit(4)
                ->get(),
        ]);
    }

    /**
     * Buscador global: recetas, lotes, pedidos y registros de auditoría.
     */
    public function buscar(Request $request): JsonResponse
    {
        $datos = $request->validate([
            'q' => ['nullable', 'string', 'max:100'],
        ]);

        $termino = trim($datos['q'] ?? '');

        if (mb_strlen($termino) < 2) {
            return response()->json(['termino' => $termino, 'grupos' => []]);
        }

        $like = '%'.str_replace(['%', '_'], ['\%', '\_'], $termino).'%';

        $grupos = [];

        $recetas = Receta::where('nombre', 'ilike', $like)
            ->limit(5)
            ->get()
            ->map(fn (Receta $r) => [
                'titulo' => $r->nombre,
                'detalle' => $r->tipo_producto->etiqueta().' · '.number_format((float) $r->peso, 2).' g',
                'url' => route('recetas.index', ['buscar' => $r->nombre]),
            ]);
        if ($recetas->isNotEmpty()) {
            $grupos[] = ['tipo' => 'Recetas', 'items' => $recetas];
        }

        $lotes = Lote::with('receta')->where('codigo', 'ilike', $like)
            ->limit(5)
            ->get()
            ->map(fn (Lote $l) => [
                'titulo' => $l->codigo,
                'detalle' => ($l->receta?->nombre ?? 'Sin receta').' · '.$l->estado->etiqueta(),
                'url' => route('lotes.index', ['buscar' => $l->codigo]),
            ]);
        if ($lotes->isNotEmpty()) {
            $grupos[] = ['tipo' => 'Lotes', 'items' => $lotes];
        }

        $pedidos = Pedido::where('cliente', 'ilike', $like)
            ->limit(5)
            ->get()
            ->map(fn (Pedido $p) => [
                'titulo' => $p->cliente,
                'detalle' => $p->descripcionCantidad().' · '.$p->estado->etiqueta(),
                'url' => route('lotes.index', ['buscar' => $p->cliente]),
            ]);
        if ($pedidos->isNotEmpty()) {
            $grupos[] = ['tipo' => 'Pedidos', 'items' => $pedidos];
        }

        $logs = LogAccion::where('accion', 'ilike', $like)
            ->orWhere('componente', 'ilike', $like)
            ->orderByDesc('fecha_hora')
            ->limit(5)
            ->get()
            ->map(fn (LogAccion $l) => [
                'titulo' => $l->accion,
                'detalle' => $l->componente.' · '.$l->fecha_hora->format('d/m/Y H:i'),
                'url' => route('proyecto.index', ['buscar' => $l->accion]),
            ]);
        if ($logs->isNotEmpty()) {
            $grupos[] = ['tipo' => 'Registros', 'items' => $logs];
        }

        return response()->json(['termino' => $termino, 'grupos' => $grupos]);
    }
}
