{"content": "/* ==========================================================================
   Panel de control · Máquina de jabón
   Hoja de estilos propia: sin dependencias ni compilación (funciona offline).
   ========================================================================== */

:root {
    --fondo: #f2f6f4;
    --panel: #ffffff;
    --tinta: #0f231d;
    --tinta-suave: #5b6f68;
    --verde: #0f766e;
    --verde-oscuro: #0b5b55;
    --verde-claro: #d7efe9;
    --ambar: #b45309;
    --ambar-claro: #fef3c7;
    --peligro: #b91c1c;
    --peligro-claro: #fee2e2;
    --borde: #dbe6e1;
    --sombra: 0 1px 2px rgba(15, 35, 29, .06), 0 8px 24px -12px rgba(15, 35, 29, .18);
    --radio: 14px;
    --radio-sm: 9px;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
    margin: 0;
    font-family: "Segoe UI", system-ui, -apple-system, Roboto, Arial, sans-serif;
    background: var(--fondo);
    color: var(--tinta);
    font-size: 15px;
    line-height: 1.55;
}

a { color: var(--verde); text-decoration: none; }
a:hover { text-decoration: underline; }

h1, h2, h3, h4 { margin: 0 0 .35rem; line-height: 1.25; font-weight: 650; }
h1 { font-size: 1.6rem; }
h2 { font-size: 1.25rem; }
h3 { font-size: 1.02rem; }
p { margin: 0 0 .8rem; }
small, .pequeno { font-size: .82rem; color: var(--tinta-suave); }

/* ------------------------------------------------------------------ Barra */

.barra {
    position: sticky;
    top: 0;
    z-index: 40;
    background: linear-gradient(135deg, #0b3d38, #0f766e 60%, #12897f);
    color: #eafcf7;
    box-shadow: 0 6px 20px -12px rgba(4, 30, 27, .8);
}

.barra-superior {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: .7rem clamp(1rem, 3vw, 2rem);
    max-width: 1400px;
    margin: 0 auto;
}

.marca { display: flex; align-items: center; gap: .55rem; font-weight: 700; font-size: 1.05rem; }
.marca .burbuja {
    display: grid; place-items: center;
    width: 34px; height: 34px; border-radius: 50%;
    background: rgba(255, 255, 255, .16);
    font-size: 1.05rem;
}

.barra-usuario { margin-left: auto; display: flex; align-items: center; gap: .9rem; }
.barra-usuario .datos { text-align: right; line-height: 1.2; }
.barra-usuario .datos strong { display: block; font-size: .9rem; }
.barra-usuario .datos span { font-size: .72rem; opacity: .8; text-transform: uppercase; letter-spacing: .06em; }

.pestanas {
    display: flex;
    gap: .15rem;
    overflow-x: auto;
    padding: 0 clamp(1rem, 3vw, 2rem);
    max-width: 1400px;
    margin: 0 auto;
    scrollbar-width: none;
}
.pestanas::-webkit-scrollbar { display: none; }

.pestana {
    flex: 0 0 auto;
    padding: .62rem .85rem;
    border-radius: 10px 10px 0 0;
    color: rgba(234, 252, 247, .78);
    font-size: .86rem;
    font-weight: 600;
    white-space: nowrap;
    border-bottom: 3px solid transparent;
    transition: background .15s, color .15s;
}
.pestana:hover { background: rgba(255, 255, 255, .09); color: #fff; text-decoration: none; }
.pestana.activa { background: rgba(255, 255, 255, .14); color: #fff; border-bottom-color: #7fe3cf; }

/* -------------------------------------------------------------- Contenido */

.contenedor {
    max-width: 1400px;
    margin: 0 auto;
    padding: clamp(1rem, 2.5vw, 2rem);
}

.cabecera-pagina {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.25rem;
}
.cabecera-pagina p { margin: 0; color: var(--tinta-suave); max-width: 65ch; }

.rejilla { display: grid; gap: 1rem; }
.rejilla.dos { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }
.rejilla.tres { grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); }
.rejilla.cuatro { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }

.tarjeta {
    background: var(--panel);
    border: 1px solid var(--borde);
    border-radius: var(--radio);
    box-shadow: var(--sombra);
    padding: 1.1rem 1.2rem;
}
.tarjeta > h2, .tarjeta > h3 { display: flex; align-items: center; gap: .5rem; }
.tarjeta .pie { margin-top: .9rem; padding-top: .8rem; border-top: 1px dashed var(--borde); }

/* ---------------------------------------------------------------- Métricas */

.metrica { display: flex; flex-direction: column; gap: .15rem; }
.metrica .etiqueta { font-size: .74rem; text-transform: uppercase; letter-spacing: .07em; color: var(--tinta-suave); font-weight: 700; }
.metrica .valor { font-size: 1.75rem; font-weight: 700; letter-spacing: -.02em; }
.metrica .valor.unidad { font-size: 1.1rem; }
.metrica .nota { font-size: .8rem; color: var(--tinta-suave); }

/* ----------------------------------------------------------------- Botones */

.boton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: .4rem;
    padding: .55rem 1rem;
    border-radius: var(--radio-sm);
    border: 1px solid var(--borde);
    background: #fff;
    color: var(--tinta);
    font: inherit;
    font-weight: 600;
    font-size: .88rem;
    cursor: pointer;
    transition: transform .08s, background .15s, border-color .15s, color .15s;
}
.boton:hover { background: #f6faf8; border-color: #c7d8d1; }
.boton:active { transform: translateY(1px); }
.boton:disabled { opacity: .55; cursor: not-allowed; }
.boton.primario { background: var(--verde); border-color: var(--verde); color: #fff; }
.boton.primario:hover { background: var(--verde-oscuro); border-color: var(--verde-oscuro); }
.boton.peligro { background: var(--peligro); border-color: var(--peligro); color: #fff; }
.boton.peligro:hover { background: #991b1b; border-color: #991b1b; }
.boton.suave { background: var(--verde-claro); border-color: transparent; color: var(--verde-oscuro); }
.boton.suave:hover { background: #c6e8e0; }
.boton.minimo { padding: .35rem .6rem; font-size: .78rem; }
.boton.bloque { width: 100%; }
.boton.grande { padding: .85rem 1.2rem; font-size: 1rem; }

.grupo-botones { display: flex; flex-wrap: wrap; gap: .45rem; }

/* ----------------------------------------------------------------- Campos */

.campo { display: flex; flex-direction: column; gap: .3rem; margin-bottom: .85rem; }
.campo label { font-size: .8rem; font-weight: 650; color: var(--tinta-suave); }
.campo input, .campo select, .campo textarea {
    width: 100%;
    padding: .55rem .7rem;
    border: 1px solid var(--borde);
    border-radius: var(--radio-sm);
    background: #fff;
    font: inherit;
    color: var(--tinta);
}
.campo input:focus, .campo select:focus, .campo textarea:focus {
    outline: 2px solid rgba(15, 118, 110, .25);
    border-color: var(--verde);
}
.campo .ayuda { font-size: .76rem; color: var(--tinta-suave); }
.fila-campos { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: .8rem; }

/* --------------------------------------------------------------- Insignias */

.insignia {
    display: inline-flex;
    align-items: center;
    gap: .3rem;
    padding: .18rem .55rem;
    border-radius: 999px;
    font-size: .74rem;
    font-weight: 700;
    letter-spacing: .02em;
    background: #eef2f0;
    color: #3d4f49;
    border: 1px solid transparent;
}
.insignia.verde { background: var(--verde-claro); color: var(--verde-oscuro); }
.insignia.ambar { background: var(--ambar-claro); color: var(--ambar); }
.insignia.rojo { background: var(--peligro-claro); color: var(--peligro); }
.insignia.gris { background: #eef2f0; color: #4a5b55; }

.punto { width: 9px; height: 9px; border-radius: 50%; background: #9aa8a3; display: inline-block; }
.punto.activo { background: #16a34a; box-shadow: 0 0 0 3px rgba(22, 163, 74, .18); }
.punto.inactivo { background: #c2ccc8; }
.punto.alerta { background: var(--ambar); box-shadow: 0 0 0 3px rgba(180, 83, 9, .16); }

/* ------------------------------------------------------------------ Tablas */

.tabla-envoltura { overflow-x: auto; }
table.tabla { width: 100%; border-collapse: collapse; font-size: .88rem; }
table.tabla th {
    text-align: left;
    font-size: .74rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--tinta-suave);
    padding: .55rem .6rem;
    border-bottom: 1px solid var(--borde);
    white-space: nowrap;
}
table.tabla td { padding: .6rem; border-bottom: 1px solid #edf2f0; vertical-align: middle; }
table.tabla tr:last-child td { border-bottom: 0; }
table.tabla tbody tr:hover { background: #f8fbfa; }

/* ------------------------------------------------------------------ Alertas */

.alerta {
    border-radius: var(--radio-sm);
    padding: .7rem .9rem;
    margin-bottom: .9rem;
    font-size: .88rem;
    border: 1px solid transparent;
}
.alerta.exito { background: var(--verde-claro); border-color: #bfe4da; color: var(--verde-oscuro); }
.alerta.error { background: var(--peligro-claro); border-color: #fecaca; color: var(--peligro); }
.alerta.info { background: #e8f1fb; border-color: #cfe2f7; color: #1e4f86; }
.alerta ul { margin: .3rem 0 0; padding-left: 1.1rem; }

/* --------------------------------------------------------------- Sensores */

.sensor {
    display: flex; flex-direction: column; gap: .2rem;
    padding: .75rem .9rem;
    border: 1px solid var(--borde);
    border-radius: var(--radio-sm);
    background: #fbfdfc;
}
.sensor .nombre { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--tinta-suave); font-weight: 700; }
.sensor .dato { font-size: 1.35rem; font-weight: 700; }
.sensor .dato small { font-size: .75rem; font-weight: 600; color: var(--tinta-suave); }

/* ------------------------------------------------------------- Componente */

.componente { display: flex; flex-direction: column; gap: .7rem; }
.componente .titulo { display: flex; align-items: center; justify-content: space-between; gap: .5rem; }
.componente .acciones { display: grid; grid-template-columns: 1fr 1fr; gap: .4rem; }
.componente .pwm { display: flex; gap: .4rem; align-items: center; }
.componente .pwm input { width: 78px; padding: .4rem .5rem; border: 1px solid var(--borde); border-radius: 8px; font: inherit; text-align: center; }
.componente .pwm span { font-size: .78rem; color: var(--tinta-suave); }

/* -------------------------------------------------------------------- Chat */

.chat { display: flex; flex-direction: column; gap: .7rem; }
.chat-mensajes {
    display: flex; flex-direction: column; gap: .55rem;
    max-height: 320px; overflow-y: auto;
    padding-right: .2rem;
}
.mensaje { max-width: 88%; padding: .55rem .75rem; border-radius: 12px; font-size: .87rem; }
.mensaje.bot { background: #eef4f2; border: 1px solid #e0eae6; align-self: flex-start; border-bottom-left-radius: 4px; }
.mensaje.usuario { background: var(--verde); color: #fff; align-self: flex-end; border-bottom-right-radius: 4px; }
.mensaje .hora { display: block; font-size: .68rem; opacity: .65; margin-top: .25rem; }
.chat-form { display: flex; gap: .45rem; }
.chat-form input {
    flex: 1; padding: .55rem .75rem; border: 1px solid var(--borde);
    border-radius: 999px; font: inherit;
}
.sugerencias { display: flex; flex-wrap: wrap; gap: .35rem; }
.sugerencia {
    border: 1px dashed #c3d6cf; background: #f8fbfa; color: var(--verde-oscuro);
    border-radius: 999px; padding: .3rem .65rem; font-size: .76rem; cursor: pointer; font-weight: 600;
}
.sugerencia:hover { background: var(--verde-claro); border-style: solid; }

/* ---------------------------------------------------------------- Buscador */

.buscador { position: relative; flex: 1 1 320px; max-width: 520px; }
.buscador input {
    width: 100%; padding: .6rem .9rem .6rem 2.2rem;
    border-radius: 999px; border: 1px solid var(--borde);
    background: #fff; font: inherit;
}
.buscador .lupa { position: absolute; left: .75rem; top: 50%; transform: translateY(-50%); opacity: .55; }
.buscador-resultados {
    position: absolute; z-index: 30; top: calc(100% + .35rem); left: 0; right: 0;
    background: #fff; border: 1px solid var(--borde); border-radius: 12px;
    box-shadow: 0 18px 40px -20px rgba(15, 35, 29, .45);
    max-height: 380px; overflow-y: auto; display: none;
}
.buscador-resultados.visible { display: block; }
.buscador-resultados .grupo { padding: .45rem .75rem .2rem; }
.buscador-resultados .grupo > span {
    font-size: .68rem; text-transform: uppercase; letter-spacing: .08em;
    color: var(--tinta-suave); font-weight: 700;
}
.buscador-resultados a {
    display: block; padding: .45rem .75rem; border-radius: 8px; color: var(--tinta);
}
.buscador-resultados a:hover { background: #f0f7f4; text-decoration: none; }
.buscador-resultados a .detalle { display: block; font-size: .76rem; color: var(--tinta-suave); }
.buscador-resultados .vacio { padding: .8rem .75rem; color: var(--tinta-suave); font-size: .85rem; }

/* --------------------------------------------------------------- Ingreso */

.pantalla-ingreso {
    min-height: 100vh;
    display: grid;
    place-items: center;
    padding: 1.5rem;
    background:
        radial-gradient(1000px 500px at 15% -10%, #d9efe9, transparent),
        radial-gradient(900px 500px at 95% 110%, #e7f0ff, transparent),
        var(--fondo);
}
.tarjeta-ingreso {
    width: 100%; max-width: 430px;
    background: #fff; border: 1px solid var(--borde);
    border-radius: 18px; padding: 1.8rem;
    box-shadow: 0 30px 60px -35px rgba(11, 61, 56, .55);
}
.tarjeta-ingreso .encabezado { text-align: center; margin-bottom: 1.3rem; }
.tarjeta-ingreso .encabezado .burbuja {
    display: grid; place-items: center; width: 54px; height: 54px;
    margin: 0 auto .6rem; border-radius: 16px; font-size: 1.6rem;
    background: var(--verde-claro); color: var(--verde-oscuro);
}
.tarjeta-ingreso .pie { text-align: center; margin-top: 1rem; font-size: .86rem; color: var(--tinta-suave); }

/* ------------------------------------------------------------- Utilidades */

.fila { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; }
.entre { display: flex; align-items: center; justify-content: space-between; gap: .8rem; flex-wrap: wrap; }
.separado { margin-top: 1.2rem; }
.silencio { opacity: .7; }
.derecha { text-align: right; }
.centro { text-align: center; }
.mono { font-family: "Cascadia Code", "Consolas", monospace; font-size: .84em; }
.sin-borde { border: 0 !important; box-shadow: none !important; }
.lista-limpia { list-style: none; margin: 0; padding: 0; }
.lista-limpia li { padding: .5rem 0; border-bottom: 1px dashed var(--borde); }
.lista-limpia li:last-child { border-bottom: 0; }
.vacio-estado {
    padding: 1.5rem; text-align: center; color: var(--tinta-suave);
    border: 1px dashed var(--borde); border-radius: var(--radio-sm); background: #fbfdfc;
}

.aviso-flotante {
    position: fixed; right: 1.2rem; bottom: 1.2rem; z-index: 60;
    max-width: 340px; padding: .75rem 1rem; border-radius: 12px;
    background: #0f231d; color: #ecfdf7; font-size: .86rem;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, .6);
    opacity: 0; transform: translateY(8px); transition: opacity .2s, transform .2s;
    pointer-events: none;
}
.aviso-flotante.visible { opacity: 1; transform: translateY(0); }
.aviso-flotante.error { background: #7f1d1d; }

.pie-pagina {
    text-align: center; font-size: .78rem; color: var(--tinta-suave);
    padding: 1.6rem 1rem 2rem;
}

@media (max-width: 720px) {
    .barra-usuario .datos { display: none; }
    .metrica .valor { font-size: 1.45rem; }
    .contenedor { padding: 1rem; }
}
