function Send-Solicitud {
  param([string]$Metodo='GET', [string]$Url, $Session, [string]$Token, [string]$Json, [int]$MaxRedir=10)
  $headers = @{ 'Accept'='application/json' }
  if ($Token) { $headers['X-CSRF-TOKEN'] = $Token }
  try {
    $p = @{ Uri=$Url; Method=$Metodo; WebSession=$Session; MaximumRedirection=$MaxRedir; UseBasicParsing=$true; Headers=$headers }
    if ($Json) { $p['ContentType']='application/json'; $p['Body']=$Json }
    $r = Invoke-WebRequest @p
    $status = [int]$r.StatusCode; $content = $r.Content; $loc = $r.Headers['Location']
