    if (-not $resp) { throw }
    $status = [int]$resp.StatusCode
    $loc = $resp.Headers['Location']
    try { $reader = New-Object System.IO.StreamReader($resp.GetResponseStream()); $content = $reader.ReadToEnd(); $reader.Close() } catch { $content = '' }
