{"content": "<?php

declare(strict_types=1);

namespace App\Services;

use App\Enums\IngredienteBase;

/**
 * Cálculo proporcional de la formulación.
 *
 * El operario introduce el peso de UN ingrediente base y el sistema reparte el
 * resto según los factores de la receta. Los factores viven en
 * config/panel.php para poder ajustarlos sin tocar código.
 */
class FormulacionService
{
    /**
     * @return array<string, float>
     */
    public function factores(): array
    {
        return [
            'aceite' => (float) config('panel.formulacion.aceite', 1.0),
            'agua' => (float) config('panel.formulacion.agua', 0.38),
            'sosa' => (float) config('panel.formulacion.sosa', 0.14),
        ];
    }

    /**
     * Devuelve los gramos de cada ingrediente para un peso base dado.
     *
     * @return array<string, float>
     */
    public function calcular(IngredienteBase $base, float $peso): array
    {
        $factores = $this->factores();
        $factorBase = $factores[$base->value] ?? 0.0;

        if ($factorBase <= 0 || $peso <= 0) {
            return [];
        }

        // Primero se lleva el peso base a "una unidad de aceite" y luego se
        // reparte entre todos los ingredientes.
        $unidad = $peso / $factorBase;

        $calculos = [];
        foreach ($factores as $ingrediente => $factor) {
            $calculos[$ingrediente] = round($unidad * $factor, 2);
        }

        return $calculos;
    }

    /**
     * @param  array<string, float|int>  $calculos
     */
    public function total(array $calculos): float
    {
        return round((float) array_sum($calculos), 2);
    }
}
