<script>
    (() => {
        const factores = @json($factores);

        const base = document.getElementById('ingrediente_base');
        const peso = document.getElementById('peso');
        const campoAceite = document.getElementById('campo-aceite');
        const aceite = document.getElementById('tipo_aceite');

        const calcular = () => {
            const factorBase = factores[base.value] ?? 0;
            const gramos = Number(peso.value);

            if (!factorBase || !gramos || gramos <= 0) {
                ['aceite', 'agua', 'sosa'].forEach((i) => {
                    document.getElementById(`calc-${i}`).textContent = '—';
                });
                document.getElementById('calc-total').textContent = '—';
                return;
            }

            const unidad = gramos / factorBase;
            let total = 0;

            ['aceite', 'agua', 'sosa'].forEach((ingrediente) => {
                const valor = unidad * (factores[ingrediente] ?? 0);
                total += valor;
                document.getElementById(`calc-${ingrediente}`).textContent =
                    `${valor.toFixed(2)} g`;
            });

            document.getElementById('calc-total').textContent = `${total.toFixed(2)} g`;
        };

        const alternarAceite = () => {
            const esAceite = base.value === 'aceite';
            campoAceite.style.display = esAceite ? '' : 'none';
            aceite.required = esAceite;
        };

        base.addEventListener('change', () => { alternarAceite(); calcular(); });
        peso.addEventListener('input', calcular);

        // Aditivos dinámicos
        let indice = 1;
        document.getElementById('agregar-aditivo').addEventListener('click', () => {
            const bloque = document.createElement('div');
            bloque.className = 'fila';
            bloque.style.marginBottom = '.5rem';
            bloque.innerHTML = `
                <input type="text" name="aditivos[${indice}][nombre]" placeholder="Nombre del aditivo"
                       style="flex:1;padding:.5rem .7rem;border:1px solid var(--borde);border-radius:9px;">
                <input type="number" name="aditivos[${indice}][gramos]" placeholder="g" step="0.01" min="0"
                       style="width:100px;padding:.5rem .7rem;border:1px solid var(--borde);border-radius:9px;">`;
            document.getElementById('lista-aditivos').appendChild(bloque);
            indice += 1;
        });

        alternarAceite();
        calcular();
    })();
</script>
