{"content": "# Prueba de humo: lotes y pedidos (PowerShell 5.1, solo ASCII)
$ErrorActionPreference = 'Stop'
$base = 'http://127.0.0.1:8126'
$script:ok = 0
$script:bad = 0

function Check([string]$etiqueta, [bool]$condicion, [string]$detalle = '') {
    if ($condicion) { $script:ok++; Write-Host "  [OK]    $etiqueta" }
    else { $script:bad++; Write-Host "  [FALLO] $etiqueta $detalle" }
}

function TokenDe([string]$html) {
    $m = [regex]::Match($html, 'name="csrf-token" content="([^"]+)"')
    if ($m.Success) { return $m.Groups[1].Value }
    return [regex]::Match($html, 'name="_token" value="([^"]+)"').Groups[1].Value
}

function Pedir {
    param([string]$Url, $Session, [hashtable]$Cuerpo, [string]$Metodo = 'GET')
    try {
        $p = @{ Uri = $Url; Method = $Metodo; WebSession = $Session; UseBasicParsing = $true }
        if ($Cuerpo) { $p['Body'] = $Cuerpo }
        $r = Invoke-WebRequest @p
        return [pscustomobject]@{ Status = [int]$r.StatusCode; Content = [string]$r.Content }
    }
    catch [System.Net.WebException] {
        $resp = $_.Exception.Response
        if (-not $resp) { throw }
        $texto = ''
        try { $reader = New-Object System.IO.StreamReader($resp.GetResponseStream()); $texto = $reader.ReadToEnd(); $reader.Close() } catch { }
        return [pscustomobject]@{ Status = [int]$resp.StatusCode; Content = $texto }
    }
}

$s = New-Object Microsoft.PowerShell.Commands.WebRequestSession
$login = Pedir -Url "$base/login" -Session $s
$token = TokenDe $login.Content
Pedir -Url "$base/login" -Session $s -Metodo POST -Cuerpo @{ _token = $token; email = 'admin@jabon.local'; password = 'admin1234' } | Out-Null

Write-Host '== Lotes y pedidos =='
$pagina = Pedir -Url "$base/lotes" -Session $s
Check 'GET /lotes responde 200' ($pagina.Status -eq 200) "-> $($pagina.Status)"
Check 'la pestana aparece en el menu' ($pagina.Content -match 'Lotes y pedidos')
Check 'ofrece crear un lote' ($pagina.Content -match 'Nuevo lote')
Check 'ofrece crear un pedido' ($pagina.Content -match 'Nuevo pedido')
$token = TokenDe $pagina.Content

$recetaId = [regex]::Match($pagina.Content, 'id="receta_id"[\s\S]*?<option value="(\d+)"').Groups[1].Value
Check 'hay una receta disponible para el lote' ($recetaId -ne '')

$crearLote = Pedir -Url "$base/lotes" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; receta_id = $recetaId; estado = 'en_proceso'
}
Check 'POST /lotes crea el lote' ($crearLote.Status -eq 200) "-> $($crearLote.Status)"
Check 'el codigo se genera automaticamente' ($crearLote.Content -match 'LOTE-\d{4}-\d{4}')
Check 'el lote queda en proceso' ($crearLote.Content -match 'En proceso')

$crearPedido = Pedir -Url "$base/lotes" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; cliente = 'Cliente Mayorista'; cantidad_unidades = '24'; estado = 'pendiente'
}
Check 'POST /pedidos registra el pedido' ($crearPedido.Content -match 'Cliente Mayorista')
Check 'muestra la cantidad en unidades' ($crearPedido.Content -match '24 unidades')

$sinCantidad = Pedir -Url "$base/lotes" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; cliente = 'Sin cantidad'; estado = 'pendiente'
}
Check 'rechaza un pedido sin cantidad' ($sinCantidad.Content -match 'al menos una')

# Asignar el lote al pedido (relacion muchos a muchos)
$pagina2 = Pedir -Url "$base/lotes" -Session $s
$pedidoId = [regex]::Match($pagina2.Content, '/pedidos/(\d+)/lotes').Groups[1].Value
$loteId = [regex]::Match($pagina2.Content, 'name="lote_id"[\s\S]*?<option value="(\d+)"').Groups[1].Value
Check 'se detecta el pedido a asignar' ($pedidoId -ne '')
Check 'se detecta el lote disponible' ($loteId -ne '')

$asignar = Pedir -Url "$base/pedidos/$pedidoId/lotes" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; lote_id = $loteId
}
Check 'asigna el lote al pedido' ($asignar.Content -match 'Lote asignado')
Check 'el pedido muestra el lote asignado' ($asignar.Content -match 'LOTE-\d{4}-\d{4}')

$quitar = Pedir -Url "$base/pedidos/$pedidoId/lotes/$loteId" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; _method = 'DELETE'
}
Check 'desasigna el lote' ($quitar.Content -match 'desasignado')

$completar = Pedir -Url "$base/lotes/$loteId/estado" -Session $s -Metodo POST -Cuerpo @{
    _token = $token; _method = 'PATCH'; estado = 'completado'; peso_producido = '12.5'
}
Check 'cambia el estado del lote a completado' ($completar.Content -match 'Completado')
Check 'guarda el peso producido' ($completar.Content -match '12.5')

Write-Host ''
Write-Host "Resultado: $($script:ok) correctas, $($script:bad) fallidas"
if ($script:bad -eq 0) { exit 0 } else { exit 1 }
