content.arguments:
{"content": "# Verificacion integral: 8 pestanas y 3 roles (PowerShell 5.1, solo ASCII)
$ErrorActionPreference = 'Stop'
$base = 'http://127.0.0.1:8126'
$script:ok = 0
$script:bad = 0

function Check([string]$etiqueta, [bool]$condicion, [string]$detalle = '') {
    if ($condicion) { $script:ok++; Write-Host "  [OK]    $etiqueta" }
    else { $script:bad++; Write-Host "  [FALLO] $etiqueta $detalle" }
}

function TokenDe([string]$html) {
    $m = [regex]::Match($html, 'name="csrf-token" content="([^"]+)"')
    if ($m.Success) { return $m.Groups[1].Value }
    return [regex]::Match($html, 'name="_token" value="([^"]+)"').Groups[1].Value
}

function Pedir {
    param([string]$Url, $Session, [hashtable]$Cuerpo, [string]$Metodo = 'GET')
    try {
        $p = @{ Uri = $Url; Method = $Metodo; WebSession = $Session; UseBasicParsing = $true }
        if ($Cuerpo) { $p['Body'] = $Cuerpo }
        $r = Invoke-WebRequest @p
        return [pscustomobject]@{ Status = [int]$r.StatusCode; Content = [string]$r.Content }
    }
    catch [System.Net.WebException] {
        $resp = $_.Exception.Response
        if (-not $resp) { throw }
        $texto = ''
        try { $reader = New-Object System.IO.StreamReader($resp.GetResponseStream()); $texto = $reader.ReadToEnd(); $reader.Close() } catch { }
        return [pscustomobject]@{ Status = [int]$resp.StatusCode; Content = $texto }
    }
}

function Entrar([string]$email, [string]$clave) {
    $sesion = New-Object Microsoft.PowerShell.Commands.WebRequestSession
    $login = Pedir -Url "$base/login" -Session $sesion
    $t = TokenDe $login.Content
    $panel = Pedir -Url "$base/login" -Session $sesion -Metodo POST -Cuerpo @{ _token = $t; email = $email; password = $clave }
    return [pscustomobject]@{ Sesion = $sesion; Panel = $panel }
}

# ---------------------------------------------------------------- Administrador
Write-Host '== Administrador: las ocho pestanas =='
$admin = Entrar 'admin@jabon.local' 'admin1234'
Check 'el administrador entra' ($admin.Panel.Content -match 'Administrador')

$paginas = @(
    @('/', 'Asistente del proyecto'),
    @('/maquina', 'Control de la ma'),
    @('/recetas', 'Nueva receta'),
    @('/perfiles', 'Perfiles guardados'),
    @('/proyecto', 'Proyecto y registros'),
    @('/reportes', 'Generar informe'),
    @('/lotes', 'Lotes de producci'),
    @('/desarrolladores', 'Herramientas utilizadas'),
    @('/usuarios', 'Usuarios del sistema')
)

foreach ($p in $paginas) {
    $r = Pedir -Url "$base$($p[0])" -Session $admin.Sesion
    Check "GET $($p[0]) = 200" ($r.Status -eq 200) "-> $($r.Status)"
    Check "GET $($p[0]) tiene contenido esperado" ($r.Content -match $p[1])
}

$menu = (Pedir -Url "$base/" -Session $admin.Sesion).Content
foreach ($etiqueta in @('Inicio', 'Control de la m', 'Formulaci', 'Perfiles de funcionamiento', 'Proyecto y registros', 'Reportes e informes', 'Lotes y pedidos', 'Usuarios', 'Desarrolladores')) {
    Check "el menu incluye $etiqueta" ($menu -match [regex]::Escape($etiqueta))
}

# ---------------------------------------------------------------- Operador
Write-Host '== Operador: controla la maquina, no gestiona usuarios =='
$op = Entrar 'operador2@test.bo' 'claveSegura123'
Check 'el operador entra' ($op.Panel.Content -match 'Operador')
Check 'el operador accede a /maquina' ((Pedir -Url "$base/maquina" -Session $op.Sesion).Status -eq 200)
Check 'el operador accede a /reportes' ((Pedir -Url "$base/reportes" -Session $op.Sesion).Status -eq 200)
Check 'el operador recibe 403 en /usuarios' ((Pedir -Url "$base/usuarios" -Session $op.Sesion).Status -eq 403)
$menuOp = (Pedir -Url "$base/" -Session $op.Sesion).Content
Check 'el operador no ve la pestana Usuarios' (-not ($menuOp -match 'Usuarios'))

# ---------------------------------------------------------------- Visualizador
Write-Host '== Visualizador: solo Inicio y Proyecto =='
$adminSesion = $admin.Sesion
$form = Pedir -Url "$base/usuarios" -Session $adminSesion
$t = TokenDe $form.Content
Pedir -Url "$base/usuarios" -Session $adminSesion -Metodo POST -Cuerpo @{
    _token = $t; nombre = 'Visitante Final'; email = 'visitante.final@test.bo'; password = 'claveSegura123'; rol = 'visualizador'; activo = '1'
} | Out-Null

$vis = Entrar 'visitante.final@test.bo' 'claveSegura123'
Check 'el visualizador entra' ($vis.Panel.Content -match 'Visualizador')
Check 'el visualizador ve el inicio' ((Pedir -Url "$base/" -Session $vis.Sesion).Status -eq 200)
Check 'el visualizador ve /proyecto' ((Pedir -Url "$base/proyecto" -Session $vis.Sesion).Status -eq 200)
Check 'el visualizador ve /desarrolladores' ((Pedir -Url "$base/desarrolladores" -Session $vis.Sesion).Status -eq 200)
Check 'el visualizador recibe 403 en /maquina' ((Pedir -Url "$base/maquina" -Session $vis.Sesion).Status -eq 403)
Check 'el visualizador recibe 403 en /reportes' ((Pedir -Url "$base/reportes" -Session $vis.Sesion).Status -eq 403)
Check 'el visualizador recibe 403 en /recetas' ((Pedir -Url "$base/recetas" -Session $vis.Sesion).Status -eq 403)
$menuVis = (Pedir -Url "$base/" -Session $vis.Sesion).Content
Check 'su menu no muestra Control' (-not ($menuVis -match 'Control de la m'))
Check 'su menu si muestra Proyecto' ($menuVis -match 'Proyecto y registros')

# ---------------------------------------------------------------- Descarga PDF
Write-Host '== Descarga de informes =='
$rep = Pedir -Url "$base/reportes" -Session $adminSesion
$enlace = [regex]::Match($rep.Content, '/reportes/(\d+)/descargar').Groups[1].Value
Check 'hay un informe para descargar' ($enlace -ne '')

$descarga = Invoke-WebRequest -Uri "$base/reportes/$enlace/descargar" -WebSession $adminSesion -UseBasicParsing
Check 'la descarga responde 200' ($descarga.StatusCode -eq 200)
Check 'el archivo descargado es un PDF' ($descarga.Headers['Content-Type'] -match 'pdf')

Write-Host ''
Write-Host "Resultado: $($script:ok) correctas, $($script:bad) fallidas"
if ($script:bad -eq 0) { exit 0 } else { exit 1 }
", "file_path": "C:\Users\io\Documents\PROYECTO\proyectolocal\_smoke4.ps1"}

