            'perfilActivo' => $perfilActivo,
            'pwm' => $perfilActivo?->pwm() ?? Perfil::PWM_POR_DEFECTO,
            'automatizacion' => $perfilActivo?->automatizacionIr() ?? [],
            'intervalosAceite' => $perfilActivo?->intervalosAceite() ?? [],
            'programaciones' => Programacion::with('user')->where('activa', true)->orderBy('id')->get(),
            'actual' => $this->esp32->estado(),
            'componentes' => Esp32Service::COMPONENTES,
        ]);
    }"}

