        'programaciones' => Programacion::with('user')->where('activa', true)->orderBy('id')->get(),
        'actual' => $this->esp32->estado(),
        'componentes' => Esp32Service::COMPONENTES,
        // Los pedidos abiertos se gestionan también desde aquí.
        'pedidosAbiertos' => \App\Models\Pedido::abiertos()
            ->orderByRaw("case when estado = 'pendiente' then 0 else 1 end")
            ->orderBy('fecha_entrega')
            ->limit(8)
            ->get(),
    ]);
